document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("toggle-shorts"),t=document.getElementById("toggle-tags");chrome.storage.local.get(["hideShorts","hideTags"],d=>{e.checked=!1!==d.hideShorts,t.checked=!1!==d.hideTags}),e.addEventListener("change",()=>{chrome.storage.local.set({hideShorts:e.checked})}),t.addEventListener("change",()=>{chrome.storage.local.set({hideTags:t.checked})}),document.getElementById("manage-btn").addEventListener("click",e=>{e.preventDefault(),chrome.runtime.sendMessage({action:"openPinnedPage"})})});